package dev.kristian.nullmod.entity;

import dev.kristian.nullmod.NullMod;
import javax.annotation.Nullable;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.RandomSource;

/**
 * The fixed table of skins worn by Visitors and simulated players. The server only ever
 * picks and syncs an index; the client turns the index into a texture and an arm model.
 * The textures are generated by {@code tools/gen_skins.py}, which prints this exact table.
 * Indices are stable: worlds store them, so new skins may only be appended.
 */
public final class SkinSet {
    public enum Category {
        /** Completely black bodies, some with faint white eyes. */
        BLACK,
        /** The magenta and black missing texture. */
        MISSING,
        /** Ordinary skins damaged like a corrupted file. */
        DISTORTED,
        /** Simple early-2010s looking skins. */
        OLD
    }

    /**
     * @param slim whether the skin uses the three pixel wide arm model
     * @param eyes whether a {@code skin_<n>_eyes.png} glow mask exists for it
     */
    public record Skin(int index, Category category, boolean slim, boolean eyes) {
    }

    private static final Skin[] SKINS = {
            new Skin(0, Category.BLACK, false, false),
            new Skin(1, Category.BLACK, false, false),
            new Skin(2, Category.BLACK, false, true),
            new Skin(3, Category.BLACK, false, true),
            new Skin(4, Category.BLACK, true, true),
            new Skin(5, Category.BLACK, false, true),
            new Skin(6, Category.BLACK, false, true),
            new Skin(7, Category.BLACK, true, true),
            new Skin(8, Category.MISSING, false, false),
            new Skin(9, Category.MISSING, true, false),
            new Skin(10, Category.MISSING, false, false),
            new Skin(11, Category.MISSING, false, false),
            new Skin(12, Category.MISSING, false, false),
            new Skin(13, Category.MISSING, false, false),
            new Skin(14, Category.DISTORTED, false, false),
            new Skin(15, Category.DISTORTED, false, false),
            new Skin(16, Category.DISTORTED, false, false),
            new Skin(17, Category.DISTORTED, false, false),
            new Skin(18, Category.DISTORTED, true, false),
            new Skin(19, Category.DISTORTED, false, false),
            new Skin(20, Category.DISTORTED, true, false),
            new Skin(21, Category.DISTORTED, false, false),
            new Skin(22, Category.DISTORTED, false, false),
            new Skin(23, Category.DISTORTED, false, false),
            new Skin(24, Category.OLD, false, false),
            new Skin(25, Category.OLD, false, false),
            new Skin(26, Category.OLD, true, false),
            new Skin(27, Category.OLD, false, false),
            new Skin(28, Category.OLD, false, false),
            new Skin(29, Category.OLD, true, false),
            new Skin(30, Category.OLD, false, false),
            new Skin(31, Category.OLD, false, false),
            new Skin(32, Category.OLD, true, false),
            new Skin(33, Category.OLD, false, false),
            new Skin(34, Category.OLD, false, false),
            new Skin(35, Category.OLD, true, false),
            new Skin(36, Category.OLD, false, false),
            new Skin(37, Category.OLD, true, false),
            new Skin(38, Category.OLD, false, false),
            new Skin(39, Category.OLD, false, false),
    };

    private static final ResourceLocation[] TEXTURES = new ResourceLocation[SKINS.length];
    private static final ResourceLocation[] EYES = new ResourceLocation[SKINS.length];
    private static final int[][] BY_CATEGORY = new int[Category.values().length][];

    static {
        for (int i = 0; i < SKINS.length; i++) {
            if (SKINS[i].index() != i) {
                throw new IllegalStateException("SkinSet table out of order at " + i);
            }
            TEXTURES[i] = NullMod.id("textures/entity/skins/skin_" + i + ".png");
            EYES[i] = SKINS[i].eyes() ? NullMod.id("textures/entity/skins/skin_" + i + "_eyes.png") : null;
        }
        for (Category category : Category.values()) {
            int count = 0;
            for (Skin skin : SKINS) {
                if (skin.category() == category) {
                    count++;
                }
            }
            int[] indices = new int[count];
            int n = 0;
            for (Skin skin : SKINS) {
                if (skin.category() == category) {
                    indices[n++] = skin.index();
                }
            }
            BY_CATEGORY[category.ordinal()] = indices;
        }
    }

    private SkinSet() {
    }

    public static int count() {
        return SKINS.length;
    }

    /** Any index (also a corrupted or out-of-range one from the network) maps to a valid skin. */
    public static int sanitize(int index) {
        return Math.floorMod(index, SKINS.length);
    }

    public static Skin get(int index) {
        return SKINS[sanitize(index)];
    }

    public static ResourceLocation texture(int index) {
        return TEXTURES[sanitize(index)];
    }

    /** The glow mask for skins with faint eyes, or null. */
    @Nullable
    public static ResourceLocation eyesTexture(int index) {
        return EYES[sanitize(index)];
    }

    public static boolean slim(int index) {
        return SKINS[sanitize(index)].slim();
    }

    public static Category category(int index) {
        return SKINS[sanitize(index)].category();
    }

    /** The first (lowest index) skin of a category. */
    public static int firstOf(Category category) {
        return BY_CATEGORY[category.ordinal()][0];
    }

    /** A random skin of one category. */
    public static int random(RandomSource random, Category category) {
        int[] indices = BY_CATEGORY[category.ordinal()];
        return indices[random.nextInt(indices.length)];
    }

    /** A random skin, the category chosen by the given relative weights (BLACK, MISSING, DISTORTED, OLD). */
    public static int weighted(RandomSource random, int black, int missing, int distorted, int old) {
        int total = Math.max(0, black) + Math.max(0, missing) + Math.max(0, distorted) + Math.max(0, old);
        if (total <= 0) {
            return random(random, Category.OLD);
        }
        int pick = random.nextInt(total);
        if ((pick -= Math.max(0, black)) < 0) {
            return random(random, Category.BLACK);
        }
        if ((pick -= Math.max(0, missing)) < 0) {
            return random(random, Category.MISSING);
        }
        if (pick - Math.max(0, distorted) < 0) {
            return random(random, Category.DISTORTED);
        }
        return random(random, Category.OLD);
    }
}
